// Placeholder Firebase Messaging service worker.
// To enable FCM on web, replace this file with the one generated by
// the Firebase console or follow the Firebase Web setup instructions.

importScripts('https://www.gstatic.com/firebasejs/9.22.2/firebase-app-compat.js');
importScripts('https://www.gstatic.com/firebasejs/9.22.2/firebase-messaging-compat.js');

// TODO: Replace with your firebase config
var firebaseConfig = {
  // apiKey: "...",
};

firebase.initializeApp(firebaseConfig);
const messaging = firebase.messaging();

messaging.onBackgroundMessage(function(payload) {
  console.log('[firebase-messaging-sw.js] Received background message ', payload);
  const notificationTitle = payload.notification?.title || 'ARUCAD Message';
  const notificationOptions = {
    body: payload.notification?.body || '',
    icon: '/icons/icon-192.png'
  };

  self.registration.showNotification(notificationTitle, notificationOptions);
});
